CREATE TABLE IF NOT EXISTS sug (id INTEGER PRIMARY KEY AUTOINCREMENT, char TEXT NOT NULL, main TEXT NOT NULL, owner TEXT NOT NULL, comment TEXT NOT NULL, lvl INTEGER, voc TEXT, created TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', note TEXT NOT NULL DEFAULT '', imported INTEGER NOT NULL DEFAULT 0, iph TEXT);
CREATE TABLE IF NOT EXISTS votes (sid INTEGER NOT NULL, voter TEXT NOT NULL, iph TEXT NOT NULL, v INTEGER NOT NULL, PRIMARY KEY (sid, voter));
CREATE INDEX IF NOT EXISTS votes_ip ON votes (sid, iph);
CREATE TABLE IF NOT EXISTS rl (k TEXT PRIMARY KEY, n INTEGER NOT NULL, reset INTEGER NOT NULL);
